    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.getBdchrgInfo(selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15100.slc_bdchrgTpCd_onchange' }); }
};

/**
