        $c.util.onUploadClick($c.util.getComponent('mpd_files'))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15100.btn_fileBrowse_onclick' }); }
};

/**
 * @method
 * @name btn_delRow_onclick
 * @description btn_delRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_delRow_onclick = function(e){
    try {
        fn_delRow()  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_delRow — 폼·DOM 의존(B-7)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15100.btn_delRow_onclick' }); }
