///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name CheckReqInfo_Cellphone
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CheckReqInfo_Cellphone = async function (fm) { try { const v = (fm && fm.getValue) ? fm.getValue() : (fm && fm.value != null ? fm.value : null); if (v == null || String(v) === '') { return true; } if (!$c.str.isMobilePhone(String(v))) { await $c.win.alert('휴대전화번호 형식을 확인해 주세요.'); return false; } return true; } catch (_e) { return true; } };

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_objInstNm').getValue()) === 0) {
        await $c.win.alert("피합병 대상기관을 선택하십시오.");
        $c.util.getComponent("ipt_objInstNm").focus();
        return;
    } else {
        if ($c.util.getComponent("dma_searchReq").get("objInstCd") === $c.util.getComponent("dma_searchReq").get("isurCd")) {
            await $c.win.alert("피합병 대상기관으로 해당 발행기관을 선택할 수 없습니다.");
            $c.util.getComponent("dma_searchReq").set("objInstCd", "");
            $c.util.getComponent("ipt_objInstNm").setValue("");
            $c.util.getComponent("ipt_objInstNm").focus();
            return;
        }
    }
    await scwin.tx_fn_search('/company/company.do?method=searchBndListBySplitMerge&pageDiv=merge');
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    await scwin.tx_fn_save('/company/company.do?method=saveMergeAppl');
};

/**
 * @method
 * @name checkData
 * @description check Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function () {
    const fm = (document.SendForm || { elements: [] });
    const _mktact_cd = $c.util.getComponent("dma_searchReq").get("bndMktactTpCd");
    const _now_time = dma_hiddenStore.get("areaNowTimer");
    const _isur_cd = $c.util.getComponent("dma_searchReq").get("isurCd");
    if (!applTmCheck(_mktact_cd, _now_time, _isur_cd)) {
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_procsReqDd').getValue()) === 0) {
        await $c.win.alert("적용희망일을 입력하십시오.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return false;
    } else {
        if (WebSquare.date.getCurrentServerDate("yyyyMMdd") >= $c.util.getComponent('cal_procsReqDd').getValue().replace("-", "").replace("-", "")) {
            await $c.win.alert("적용희망일은 익일 이후만 입력가능합니다.");
            $c.util.getComponent("cal_procsReqDd").focus();
            return;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('cal_genmeetHldDd').getValue()) === 0) {
                await $c.win.alert("주주 임시총회일을 입력하십시오.");
                $c.util.getComponent("cal_genmeetHldDd").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('cal_rsnOccrDd').getValue()) === 0) {
                    await $c.win.alert("변경등기일을 입력하십시오.");
                    $c.util.getComponent("cal_rsnOccrDd").focus();
                    return false;
                } else {
                    if (!await scwin.CheckChgIsuNm(fm)) {
                        return false;
                    } else {
                        if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
                            return false;
                        } else {
                            if ($c.str.getByteLength($c.util.getComponent('slc_bdchrgTpCd').getValue()) === 0) {
                                return false;
                            } else {
                                if (!await scwin.CheckReqInfo_Cellphone(fm)) {
                                    return false;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    return true;
};

/**
 * @method
 * @name CheckChgIsuNm
 * @description Check Chg Isu Nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CheckChgIsuNm = async function (fm) {
    let isNull = false;
    let checkNum = 0;
    $i = 0;
    for (let r = 0, n = $c.util.getComponent('dlt_result').getRowCount(); r < n; r++) {
        if ($c.util.getComponent('dlt_result').getRowCount() === 1) {
            if ((['true', 'Y', '1', 'on'].indexOf(String($c.util.getComponent('dlt_result').getCellData(r, 'check'))) >= 0)) {
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData(0, 'chgIsuNm')) === 0) {
                    await $c.win.alert("선택된 합병대상 종목의 변경후 한글종목명을 입력하십시오.");
                    ipt_chgIsuNm.focus();
                    isNull = true;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData(0, 'chgIsuEngNm')) === 0) {
                        await $c.win.alert("선택된 합병대상 종목의 변경후 영문종목명을 입력하십시오.");
                        ipt_chgIsuEngNm.focus();
                        isNull = true;
                    }
                }
                checkNum = checkNum + 1;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData(0, 'chgIsuNm')) > 0) {
                    ipt_chgIsuNm.setValue('');
                }
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData(0, 'chgIsuEngNm')) > 0) {
                    ipt_chgIsuEngNm.setValue('');
                }
            }
        } else {
            if ((['true', 'Y', '1', 'on'].indexOf(String($c.util.getComponent('dlt_result').getCellData(r, 'check'))) >= 0)) {
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData($i, 'chgIsuNm')) === 0) {
                    await $c.win.alert("선택된 합병대상 종목의 변경후 한글종목명을 입력하십시오.");
                    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    isNull = true;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData($i, 'chgIsuEngNm')) === 0) {
                        await $c.win.alert("선택된 합병대상 종목의 변경후 영문종목명을 입력하십시오.");
                        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                        isNull = true;
                    }
                }
                checkNum = checkNum + 1;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData($i, 'chgIsuNm')) > 0) {
                    $c.util.getComponent('dlt_result').setCellData($i, 'chgIsuNm', (''));
                }
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData($i, 'chgIsuEngNm')) > 0) {
                    $c.util.getComponent('dlt_result').setCellData($i, 'chgIsuEngNm', (''));
                }
            }
        }
        $i = $i + 1;
    }
    if (checkNum === 0) {
        await $c.win.alert("하나 이상의 종목을 선택하십시오.");
        ipt_checkAll.focus();
        return false;
    } else {
        if (!isNull) {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name selectAll_2
 * @description select All 2 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectAll_2 = function () {
    let checked = $("#ipt_checkAll").attr("checked");
    if (checked === "checked") {
        checked = true;
    } else {
        checked = false;
    }
    $.each($("#SendForm").find("input[name='check']"), function(i) {
            let subChecked = $(this).attr("checked");
            if (subChecked === "checked") {
                subChecked = true;
            } else {
                subChecked = false;
            }
            if (subChecked !== checked) {
                $(this).attr("checked", checked);
            }
    });
};

/**
 * @method
 * @name setChgBasIsuNm
 * @description set Chg Bas Isu Nm 처리
 * @returns {void}
 * @hidden N
 */
scwin.setChgBasIsuNm = function () {
    const fm = (document.SendForm || { elements: [] });
    $i = 0;
    for (let r = 0, n = $c.util.getComponent('dlt_result').getRowCount(); r < n; r++) {
        if ($c.util.getComponent('dlt_result').getRowCount() === 1) {
            if ((['true', 'Y', '1', 'on'].indexOf(String($c.util.getComponent('dlt_result').getCellData(r, 'check'))) >= 0)) {
                ipt_chgIsuNm.setValue($c.util.getComponent("dma_searchReq").get("hiddenChgIsuNm"));
                ipt_chgIsuEngNm.setValue($c.util.getComponent("dma_searchReq").get("hiddenChgIsuEngNm"));
            } else {
                ipt_chgIsuNm.setValue("");
                ipt_chgIsuEngNm.setValue("");
            }
        } else {
            if ((['true', 'Y', '1', 'on'].indexOf(String($c.util.getComponent('dlt_result').getCellData(r, 'check'))) >= 0)) {
                $c.util.getComponent('dlt_result').setCellData($i, 'chgIsuNm', (fm.hidden_chg_isu_nm[$i].value));
                $c.util.getComponent('dlt_result').setCellData($i, 'chgIsuEngNm', (fm.hidden_chg_isu_eng_nm[$i].value));
            } else {
                $c.util.getComponent('dlt_result').setCellData($i, 'chgIsuNm', (""));
                $c.util.getComponent('dlt_result').setCellData($i, 'chgIsuEngNm', (""));
            }
        }
        $i = $i + 1;
    }
};

/**
 * @method
 * @name setTelNo
 * @description set Tel No 처리
 * @param {*} pTelNo pTelNo
 * @returns {void}
 * @hidden N
 */
scwin.setTelNo = function (pTelNo) {
    if (pTelNo != null && pTelNo !== '') {
        const pTelNoArr = pTelNo.split('-');
        if (pTelNoArr.length === 3) {
            if (pTelNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctTelNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctTelNo1').setValue(pTelNoArr[0]);
            }
            $c.util.getComponent('ipt_apctTelNo2').setValue(pTelNoArr[1]);
            $c.util.getComponent('ipt_apctTelNo3').setValue(pTelNoArr[2]);
        } else {

        }
    }
};

